  final List<String> list=keyring.getItems(this.createAttributes(String.format("%s://%s@%s:%d",scheme,user,hostname,port)));
  if (list != null) {
    try {
      return String.valueOf(keyring.getSecret(list.get(0)));
    } catch (IndexOutOfBoundsException e) {
      return null;
